function rankReviewFor(q){const table=data.rankings?.find(x=>x.tour===q.tour),r=C.rankingReview(table);return r?.state==='conflict'&&r.conflicts.some(x=>x.playerId===q.id)?r:null;}
function rankReviewBadge(table){const r=C.rankingReview(table);return r?`<button class="ranking-review-badge ${r.state==='conflict'?'review-pending':'review-confirmed'}" data-action="sources" data-rank-review="${e(table.tour)}" title="${e(r.state==='conflict'?'不同来源的本期名次或积分存在差异，查看核验详情':'已对照官方本期完整前100；不代表实时或自动更新')}">${ic('info')}${e(r.label)}</button>`:'';}
function rankingEvidenceDetail(table){const r=C.rankingReview(table);if(!r)return '';const pending=r.state==='conflict';return `<details class="detail-accordion ranking-evidence"><summary>${e(r.label)} · ${e(r.rankingDate)}</summary><p>${e(r.note)}</p><p>核对时间：${e(sourceTime(r.checkedAt))}</p>${pending?`<div class="ranking-discrepancies">${r.conflicts.map(c=>`<div><b>${e(p(c.playerId)?.name||c.playerId)}</b><span>本站 ${c.current.rank} 位 · ${c.current.points.toLocaleString('en-US')} 分</span><span>另一来源 ${c.candidate.rank} 位 · ${c.candidate.points.toLocaleString('en-US')} 分</span></div>`).join('')}</div>`:''}${ext(r.sourceUrl,pending?'候选来源说明':'官方榜单','btn ghost small')}</details>`;}
